//! Retry configuration.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct RetryConfig {
    /// Total attempts allowed, including the first call. Must be >= 1.
    pub max_attempts: u32,
    /// Base delay before the first retry, in milliseconds.
    pub base_delay_ms: u64,
    /// Maximum delay between retries, in milliseconds.
    pub max_delay_ms: u64,
}

impl RetryConfig {
    /// Computes the delay before a retry, where `retry_number` starts at one.
    pub fn delay_for_retry(&self, retry_number: u32) -> u64 {
        if retry_number == 0 || self.max_delay_ms == 0 {
            return 0;
        }

        let exponent = retry_number - 1;
        let multiplier = 1u64.checked_shl(exponent).unwrap_or(u64::MAX);
        self.base_delay_ms
            .checked_mul(multiplier)
            .unwrap_or(u64::MAX)
            .min(self.max_delay_ms)
    }
}

impl Default for RetryConfig {
    fn default() -> Self {
        Self {
            max_attempts: 1,
            base_delay_ms: 0,
            max_delay_ms: 0,
        }
    }
}

#[cfg(test)]
mod tests {
    use super::RetryConfig;

    #[test]
    fn delay_growth_saturates_without_overflow() {
        let config = RetryConfig {
            max_attempts: u32::MAX,
            base_delay_ms: u64::MAX,
            max_delay_ms: 123,
        };
        assert_eq!(config.delay_for_retry(1), 123);
        assert_eq!(config.delay_for_retry(u32::MAX), 123);
    }
}

//! Error taxonomy for the job runner.
